268    /**
269     * 新开一场。
270     * 会话号由 stampId() 生成：本机本地时间的年月日时分秒毫秒（17 位）加 3 位随机数字，共 20 位纯数字，
271     * 和 0.4 src/utils/Utils.ts 的 createSessionId 一样（用 getHours 等本地时区，不用 UTC）。
272     * 所有新会话（前台、后台、小会话）都走这里，不另写一套号。
273     * 旧的 8 位十六进制会话号仍能打开、继续用，不迁移已有数据。
274     * @param input 种类、嵌在哪场里、模型、思考档，加上插件给记录加的那些项；原样带进记录。
275     * @returns 新会话，状态 done，对话是空的。
276     * 副作用：写库。
277     */
278    create(input: NewSession): Session {
279      //M 读取全局默认配置并预编译查重语句，避免高并发同毫秒生成会话号时撞号覆盖。
280      const config = this.ctx.resources.config;
281      const existsQuery = this.ctx.resources.db.query('SELECT 1 FROM sessions WHERE id = ?');
282  
283      //M 同一毫秒撞上时换一个再试（主键拦下）。save() 是 INSERT OR REPLACE，创建时先查重，免得把旧会话盖掉。
284      for (let attempt = 0; ; attempt += 1) {
285        const id = stampId();
286        const exists = existsQuery.get(id);
287        if (exists !== null) {
288          //G 连撞好几次 → 不再试，抛错。
289          if (attempt >= 5) {
290            throw new Error('生成会话号连续撞上已有记录');
291          }
292          continue;
293        }
294  
295        //M 号没人用：拼一份新记录（模型、思考档没给就用配置里的），存库，记进 live。
296        const row: SessionRow = {
297          ...input,
298          id,
299          model: input.model ?? config.defaultModel,
300          thinking: input.thinking ?? config.thinking,
301          state: 'done',
302          reply: '',
303          messages: [],
304          updatedAt: Date.now(),
305        };
306        //M 按配置补齐模型与思考档并创建新会话实例，随后写入持久化列表。
307        const session = new Session(row, this.ctx);
308        //M 立即落库持久化并缓存到 live 表，确保后续消息与停止动作能命中同一实例。
309        session.save();
310        this.live.set(row.id, session);
311        return session;
312      }
313    }
314  
```

### 解释
- 输入 NewSession；输出新的 Session；副作用写库。
- 三步见下面三个子块。

