315    /**
316     * 打开一场。
317     * @param id 会话号。
318     * @returns 会话对象。同一场永远交回同一个对象。
319     * @throws 没有这场时抛错。
320     */
321    open(id: string): Session {
322      //M 先查内存里已打开的会话对象，直接复用以保持运行开关和未入队消息一致。
323      const opened = this.live.get(id);
324      if (opened !== undefined) return opened;
325  
326      //M 库里的两块读出来，拼回一份记录。
327      const sql = 'SELECT meta, messages FROM sessions WHERE id = ?';
328      const query = this.ctx.resources.db.query(sql);
329      const stored = query.get(id) as { meta: string; messages: string } | null;
330  
331      //G 库里没有 → 抛错。
332      if (stored === null) {
333        throw new Error(`没有这场会话：${id}`);
334      }
335  
336      //M 解析磁盘元信息与对话历史重建会话实例，并放入 live 供同一场对话复用。
337      const meta = JSON.parse(stored.meta) as SessionMeta;
338      const messages = JSON.parse(stored.messages) as piAi.Message[];
339      const session = new Session({ ...meta, messages }, this.ctx);
340      this.live.set(id, session);
341      return session;
342    }
343  
```

### 解释
- 输入会话号；输出 Session，同一场永远交回同一个对象。
