344    /**
345     * 找会话：给的几项都相等的那些。只读记录（不带对话），不打开。
346     * @param where 照哪几项找，比如 { state: 'running' }；插件给记录加的项也能用，比如 { bot: '助手', kind: 'work' }。
347     * @returns 记录，最近动过的在前。
348     */
349    find(where: Partial<SessionMeta>): SessionMeta[] {
350      //M 每一项都用 json_extract 从 meta 里取出来比，所以插件加的项不用改表也能拿来找。
351      let sql = 'SELECT meta FROM sessions WHERE 1 = 1';
352      /** 填进 SQL 里问号的值：每一项两个，先是 JSON 路径（$.state），再是要等于的值。 */
353      const values: (string | number)[] = [];
354      //M 逐条追加过滤键到 WHERE 子句与绑定参数，最后按更新时间倒序返回。
355      textModule.eachEntry(where, (key, value) => {
356        sql += ' AND json_extract(meta, ?) = ?';
357        values.push(`$.${key}`, value as string | number);
358      });
359      sql += " ORDER BY json_extract(meta, '$.updatedAt') DESC";
360  
361      //M 查出来的每行只有 meta 一列，解析回记录。
362      const query = this.ctx.resources.db.query(sql);
363      const found = query.all(...values) as { meta: string }[];
364      return found.map((item) => JSON.parse(item.meta) as SessionMeta);
365    }
366  
```

### 解释
- L344–L348：文档注释：例子 `{ state: 'running' }`、`{ bot: '助手', kind: 'work' }`；交回记录，最近动过的在前。
- L349：`find(where: Partial<SessionMeta>): SessionMeta[]`。
- L350–L351：起始 SQL `SELECT meta FROM sessions WHERE 1 = 1`（后面统一接 AND）。
- L352–L353：`values` 填问号的值：每项两个，先 JSON 路径再值。
- L354–L358：`textModule.eachEntry(where, …)`：每项接一段 ` AND json_extract(meta, ?) = ?`，values 里推 `$.key` 和值。
- L359：接 `ORDER BY json_extract(meta, '$.updatedAt') DESC`。
- L361–L363：执行查询 `query.all(...values)`，每行只有 meta 一列。
- L364：逐行 `JSON.parse` 成 SessionMeta 交回。
- L365：函数结束。L366：空行。

