396    /**
397     * 用 pi 发一次模型请求。不管会话怎么走，也不存状态：给它什么请求它发什么。
398     * 会话循环每一步调它（Session.loop）；model-fallback 换模型再试时也调它（ctx.sessions.chat）。
399     * @param request 模型、思考档、提示词、对话、工具、取消信号。
400     * @returns 模型回的整条（文字、工具调用都在里面）。
401     * @throws 试够了次数还是不成、或者被喊停掐断时抛错；Session.run 接住。
402     * 副作用：发 HTTP 请求；每失败一次发一次 model/failed。
403     */
404    async chat(request: ChatRequest): Promise<piAi.AssistantMessage> {
405      /** 建好的供应商、模型和重试的配置，都在 resources 里（src7/Resources.ts）。 */
406      const resources = this.ctx.resources;
407      const retry = resources.config.retry;
408      //M 按“供应商/模型”名查出配置好的 pi 模型定义与参数，供下面构建上下文和重连使用。
409      const model = resources.getModel(request.model);
410  
411      //M 拼 pi 要的上下文：提示词的段落用空行连成一段。
412      const systemPrompt = request.system.join('\n\n');
413      const context: piAi.Context = {
414        systemPrompt,
415        messages: request.messages,
416        tools: request.tools,
417      };
418  
419      //M 请求选项：pi 自己不重试（maxRetries 0），重试交给下面的 retryAssistantCall。
420      const options: piAi.SimpleStreamOptions = {
421        signal: request.signal,
422        timeoutMs: retry.timeoutMs,
423        maxRetries: 0,
424      };
425  
426      //M 思考档不是 off 才传 reasoning；off 就不传，模型不思考。
427      if (request.thinking !== 'off') {
428        options.reasoning = request.thinking;
429      }
430  
431      //M 重试的规矩：临时的错（断网、限流、超时）隔一会儿再试，最多再试 retry.times 次；喊停了不再试。
432      //M   重试、判断哪种错值得再试，都是 pi 的 retryAssistantCall 做的。
433      const policy: piAi.RetryPolicy = {
434        enabled: true,
435        maxRetries: retry.times,
436        baseDelayMs: retry.waitMs,
437      };
438  
439      //M 发一次：每次失败（stopReason 是 error）发一次通知 model/failed，重试的那几次插件也看得到；被喊停的 aborted 不发。
440      const send = async (): Promise<piAi.AssistantMessage> => {
441        const start = Date.now();
442        const answer = await resources.models.completeSimple(model, context, options);
443        if (answer.stopReason !== 'error') return answer;
444  
445        const failed: ModelFailed = {
446          session: request.session,
447          model: request.model,
448          error: answer.errorMessage ?? '',
449          ms: Date.now() - start,
450        };
451        this.ctx.emit('model/failed', failed);
452        return answer;
453      };
454  
455      //M 发请求，失败了照上面的规矩再试。
456      const answer = await piAi.retryAssistantCall(send, policy, request.signal);
457  
458      //G pi 把失败写在回答的 stopReason 里，不抛错。出错、被喊停都在这里统一抛出去。
459      if (answer.stopReason === 'error' || answer.stopReason === 'aborted') {
460        const reason = answer.errorMessage ?? `模型请求没成（${answer.stopReason}）`;
461        throw new Error(reason);
462      }
463      return answer;
464    }
465  }
466  
```

### 解释
- 输入 ChatRequest；输出模型回的整条 AssistantMessage（文字、工具调用都在里面）。
- 五步见下面五个子块。

