541  
542        //M 关口一，调模型之前：备好这一步的请求，交给插件挨个改（session/request）。
543        const request: ChatRequest = {
544          session: this,
545          model: this.row.model,
546          thinking: this.row.thinking,
547          system: [],
548          tools: this.ctx.tools.list(this.row.kind),
549          messages: [...this.row.messages],
550          signal,
551        };
552        await this.ctx.serial('session/request', request);
553  
554        //G 有插件喊停 → 不调模型，这一轮停在这里，理由写进 reply。
555        if (request.stop !== undefined) {
556          this.stop(request.stop);
557          return;
558        }
559  
560        //T 跟踪：调模型；插件已经给了回答（假模型）就写明没有调。
561        const vars = {
562          会话: this.id,
563          第几步: step,
564          模型: request.model,
565          对话几条: request.messages.length,
566        };
567        let doing = '调模型';
568        if (request.answer !== undefined) {
569          doing = '插件已经给了回答，不调模型';
570        }
571        this.ctx.emit('trace', 'Session.loop', doing, 'ctx.sessions.chat(request)', vars);
572  
573        //M 调模型（Sessions.chat，就在本文件上面）。插件已经给了回答（假模型）就不发请求。
